// L16 Bearer guard (defense-in-depth behind the D17 client gate).
// Returns 401 unless the request carries the shared bearer token. The wf18
// payload is real bank + Gmail PII (~2,020 Chase rows incl. Cash App / Zelle),
// so this is the NAS-side server gate that pairs with the repo-side client
// gate from D17 (Imported tab hidden + fetch skipped on demo / profileless
// loads). Either gate alone fails closed.
//
// Where the expected secret comes from:
//   1. /data/finance-events/_secrets/n8n-webhook-bearer.txt  (PREFERRED file;
//      the _-prefixed path lives on the confirmed wf18 bind mount and is
//      skipped by every directory walker in this repo)
//   2. process.env fallback (N8N_WEBHOOK_BEARER / VITE_N8N_BEARER)
// On this n8n install, process.env access inside Code nodes is unreliable
// (the wf30/31/32 sandbox fix, D5 / L7), so the mounted-file path is primary.
// The companion apply script writes that file and prints the value so Darrell
// can paste the SAME value into the Vercel env var VITE_N8N_BEARER.
//
// FAILS CLOSED: if no expected secret is configured, every request is denied.
// That is deliberate — a misconfigured guard must deny PII, never leak it.

const fs = require('fs');

let expected = '';
try { expected = (fs.readFileSync('/data/finance-events/_secrets/n8n-webhook-bearer.txt', 'utf8') || '').trim(); } catch (_) {}
if (!expected) {
  try { expected = (process.env.N8N_WEBHOOK_BEARER || process.env.VITE_N8N_BEARER || '').trim(); } catch (_) {}
}

const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};
const raw = (headers.authorization || headers.Authorization || '').toString();
const presented = raw.replace(/^Bearer\s+/i, '').trim();

const authorized = !!expected && !!presented && presented === expected;

// Pass the original webhook payload through untouched (the Aggregate node
// still reads .query / .headers), with the verdict flag appended.
return [{ json: Object.assign({}, input, { __authorized: authorized }) }];

// Aggregate all ingested finance data from disk and return it as a single
// JSON response the PWA can render. Pure read-only — no mutations.
//
// PHASE 2B (2026-05-28): also surfaces per-institution bank balances from
// the new _balance.json files that workflow 15 writes (LEDGERBAL +
// AVAILBAL captured from QFX). Plus per-institution activity rollups
// (tx count, inflow, outflow, latest tx date) so the PWA's Accounts tab
// can show a real bank-derived view alongside the manual balance.
//
// Reads:
//   /data/finance-events/bank/<institution>/<txid>.json
//   /data/finance-events/bank/<institution>/_balance.json (NEW)
//   /data/finance-events/gmail/<id>.json
//   /data/chatin/_reconcile_state.json (workflow 16's state file)
//
// Output shape: { transactions, gmail_events, bank_balances, counts, page }

const fs = require('fs');
const path = require('path');

const BANK_ROOT = '/data/finance-events/bank';
const GMAIL_DIR = '/data/finance-events/gmail';
const STATE_FILES = [
  '/data/chatin/_reconcile_state.json',
  '/data/finance-events/_reconcile_state.json'
];

const input = $input.first().json || {};
const q = (input.query && typeof input.query === 'object') ? input.query : (input.body && input.body.query) || {};
const limit = Math.min(parseInt(q.limit || '500', 10) || 500, 5000);
const offset = parseInt(q.offset || '0', 10) || 0;
const institutionFilter = (q.institution || '').toLowerCase();
const statusFilter = (q.status || 'all').toLowerCase();
const sinceFilter = q.since ? new Date(q.since).getTime() : 0;

function walk(dir, out, depth) {
  if (depth > 4) return;
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (_) { return; }
  for (const e of entries) {
    if (e.name.startsWith('_')) continue;
    const full = path.join(dir, e.name);
    if (e.isDirectory()) walk(full, out, depth + 1);
    else if (e.name.endsWith('.json')) out.push(full);
  }
}

// Load reconcile state for status lookups.
let reconcileState = { reconciled_ids: {} };
for (const sf of STATE_FILES) {
  try {
    reconcileState = JSON.parse(fs.readFileSync(sf, 'utf8'));
    break;
  } catch (_) {}
}

function lookupStatus(key) {
  const r = reconcileState.reconciled_ids && reconcileState.reconciled_ids[key];
  return (r && r.status) || 'unknown';
}

// Phase 2B — gather per-institution bank balance from each _balance.json.
const bankBalances = {};
let instDirs = [];
try {
  instDirs = fs.readdirSync(BANK_ROOT, { withFileTypes: true })
    .filter(d => d.isDirectory() && !d.name.startsWith('_'))
    .map(d => d.name);
} catch (_) {}
for (const inst of instDirs) {
  const balPath = path.join(BANK_ROOT, inst, '_balance.json');
  try {
    const rec = JSON.parse(fs.readFileSync(balPath, 'utf8'));
    bankBalances[inst] = rec;
  } catch (_) {}
}

// Load bank transactions.
const bankFiles = [];
walk(BANK_ROOT, bankFiles, 0);

const bankTransactions = [];
const perInstitution = {};
for (const f of bankFiles) {
  let rec;
  try { rec = JSON.parse(fs.readFileSync(f, 'utf8')); } catch (_) { continue; }
  const t = rec.transaction || {};
  const inst = (rec.institution || '').toLowerCase();
  if (institutionFilter && inst.indexOf(institutionFilter) === -1) continue;
  const posted = t.posted || rec.captured_at;
  const postedMs = posted ? new Date(posted).getTime() : 0;
  if (sinceFilter && postedMs < sinceFilter) continue;
  const statusKey = inst + ':' + (t.fitid || (posted + '-' + t.amount + '-' + (t.name || '')));
  const status = lookupStatus(statusKey);
  if (statusFilter !== 'all' && status !== statusFilter) continue;
  bankTransactions.push({
    id: path.basename(f, '.json'),
    source: 'bank',
    institution: rec.institution,
    source_file: rec.source_file,
    posted: t.posted,
    amount: t.amount,
    name: t.name,
    memo: t.memo,
    type: t.type,
    fitid: t.fitid,
    status,
    captured_at: rec.captured_at
  });
  if (!perInstitution[inst]) perInstitution[inst] = { count: 0, in: 0, out: 0, latest: null };
  const agg = perInstitution[inst];
  agg.count += 1;
  if (typeof t.amount === 'number') {
    if (t.amount > 0) agg.in += t.amount;
    else agg.out += t.amount;
  }
  if (posted && (!agg.latest || posted > agg.latest)) agg.latest = posted;
}

// Merge per-institution rollups into bankBalances.
for (const inst of Object.keys(perInstitution)) {
  if (!bankBalances[inst]) bankBalances[inst] = { institution: inst };
  Object.assign(bankBalances[inst], {
    tx_count: perInstitution[inst].count,
    inflow_sum: Math.round(perInstitution[inst].in * 100) / 100,
    outflow_sum: Math.round(perInstitution[inst].out * 100) / 100,
    net_change: Math.round((perInstitution[inst].in + perInstitution[inst].out) * 100) / 100,
    latest_tx_date: perInstitution[inst].latest
  });
}

// Load Gmail finance events.
let gmailFiles = [];
try {
  gmailFiles = fs.readdirSync(GMAIL_DIR).filter(f => f.endsWith('.json') && !f.startsWith('_')).map(f => path.join(GMAIL_DIR, f));
} catch (_) {}

const gmailEvents = [];
for (const f of gmailFiles) {
  let rec;
  try { rec = JSON.parse(fs.readFileSync(f, 'utf8')); } catch (_) { continue; }
  const internalDate = rec.internal_date || rec.captured_at;
  if (sinceFilter && internalDate && new Date(internalDate).getTime() < sinceFilter) continue;
  const status = lookupStatus(rec.gmail_id);
  if (statusFilter !== 'all' && status !== statusFilter && status !== 'unknown') continue;
  gmailEvents.push({
    id: rec.gmail_id || path.basename(f, '.json'),
    source: 'gmail',
    from: rec.from,
    subject: rec.subject,
    snippet: rec.snippet,
    internal_date: internalDate,
    amount: rec.extracted && rec.extracted.amount,
    direction: rec.extracted && rec.extracted.direction,
    status,
    captured_at: rec.captured_at
  });
}

bankTransactions.sort((a, b) => (b.posted || '').localeCompare(a.posted || ''));
gmailEvents.sort((a, b) => (b.internal_date || '').localeCompare(a.internal_date || ''));

const pagedBank = bankTransactions.slice(offset, offset + limit);
const pagedGmail = gmailEvents.slice(0, Math.min(200, gmailEvents.length));

const statusCounts = { verified: 0, unconfirmed: 0, unexplained: 0, unknown: 0 };
for (const t of bankTransactions) statusCounts[t.status] = (statusCounts[t.status] || 0) + 1;

const institutions = Array.from(new Set(bankTransactions.map(t => t.institution).filter(Boolean))).sort();

return [{
  json: {
    served_at: new Date().toISOString(),
    counts: {
      total_bank: bankTransactions.length,
      total_gmail: gmailEvents.length,
      status_counts: statusCounts,
      institutions
    },
    bank_balances: bankBalances,
    transactions: pagedBank,
    gmail_events: pagedGmail,
    page: { limit, offset, has_more: offset + limit < bankTransactions.length }
  }
}];
